//! # archipel-fixtures
//!
//! Builds real Git repositories for tests and benchmarks, using the `git` CLI
//! (fixtures are generated by code, never committed as binaries).
//!
//! * [`TestRepo`]: a throw-away repository with helpers to write files and commit.
//! * [`project::generate_project`]: a multi-repo project covering every dashboard state.
//! * [`history::generate_history`]: a large synthetic history with merges, via `git fast-import`.

pub mod history;
pub mod project;

use std::path::{Path, PathBuf};
use std::process::{Command, Output, Stdio};

use anyhow::{Context, Result, bail};

/// Runs `git` in `dir` with an isolated, deterministic configuration and
/// returns its trimmed stdout. Fails when git exits with an error.
pub fn git(dir: &Path, args: &[&str]) -> Result<String> {
    let out = git_output(dir, args)?;
    if !out.status.success() {
        bail!(
            "git {} failed in {}: {}",
            args.join(" "),
            dir.display(),
            String::from_utf8_lossy(&out.stderr)
        );
    }
    Ok(String::from_utf8_lossy(&out.stdout).trim_end().to_owned())
}

/// Runs `git` and returns the raw output, whatever the exit status.
pub fn git_output(dir: &Path, args: &[&str]) -> Result<Output> {
    base_command(dir)
        .args(args)
        .stdin(Stdio::null())
        .output()
        .with_context(|| format!("spawning git {}", args.join(" ")))
}

/// A `git` command isolated from the user's global and system configuration.
#[must_use]
pub fn base_command(dir: &Path) -> Command {
    let mut cmd = Command::new("git");
    cmd.current_dir(dir)
        .env("GIT_CONFIG_NOSYSTEM", "1")
        .env("GIT_CONFIG_GLOBAL", null_device())
        .env("GIT_TERMINAL_PROMPT", "0")
        .env("GIT_AUTHOR_NAME", "Fixture Author")
        .env("GIT_AUTHOR_EMAIL", "author@example.com")
        .env("GIT_COMMITTER_NAME", "Fixture Author")
        .env("GIT_COMMITTER_EMAIL", "author@example.com")
        .args(["-c", "init.defaultBranch=main", "-c", "core.autocrlf=false"]);
    cmd
}

/// Path of the null device, used to disable the global Git config.
#[must_use]
pub fn null_device() -> &'static str {
    if cfg!(windows) { "NUL" } else { "/dev/null" }
}

/// A temporary repository deleted on drop.
pub struct TestRepo {
    dir: tempfile::TempDir,
}

impl TestRepo {
    /// Creates an empty repository on branch `main`.
    pub fn new() -> Result<Self> {
        let dir = tempfile::Builder::new()
            .prefix("archipel-test-")
            .tempdir()?;
        git(dir.path(), &["init", "-q", "-b", "main"])?;
        configure(dir.path())?;
        Ok(Self { dir })
    }

    /// Working tree path.
    #[must_use]
    pub fn path(&self) -> &Path {
        self.dir.path()
    }

    /// Writes a file (creating parent folders).
    pub fn write(&self, rel: &str, content: &str) -> Result<()> {
        write_file(self.path(), rel, content)
    }

    /// Runs git in the repository.
    pub fn git(&self, args: &[&str]) -> Result<String> {
        git(self.path(), args)
    }

    /// Stages everything and commits; returns the new commit id.
    pub fn commit_all(&self, message: &str) -> Result<String> {
        self.git(&["add", "-A"])?;
        self.git(&["commit", "-q", "--allow-empty", "-m", message])?;
        self.git(&["rev-parse", "HEAD"])
    }
}

/// Local configuration applied to every fixture repository.
pub fn configure(dir: &Path) -> Result<()> {
    for (k, v) in [
        ("user.name", "Fixture Author"),
        ("user.email", "author@example.com"),
        ("commit.gpgsign", "false"),
        ("tag.gpgsign", "false"),
        ("core.autocrlf", "false"),
    ] {
        git(dir, &["config", k, v])?;
    }
    Ok(())
}

/// Writes `content` to `root/rel`, creating parent folders.
pub fn write_file(root: &Path, rel: &str, content: &str) -> Result<()> {
    let path: PathBuf = root.join(rel);
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(&path, content).with_context(|| format!("writing {}", path.display()))
}
